// Minha Evolução = o antigo "Longo prazo" (mesmo visual) + a evolução por área (desporto, estudos, carreira, dinheiro, hábitos, metas)
// + tendências (hoje vs 30 dias, 3 meses e 1 ano) + gráfico de 26 semanas + análise do Spyke.
const EVA = [['Dinheiro', 'wallet', ['nw', 'sav', 'inv']], ['Estudos', 'school', ['study', 'books']], ['Desporto e corpo', 'dumbbell', ['wk', 'km', 'pace', 'vol', 'sport', 'diet']], ['Carreira', 'briefcase', ['cap', 'work']], ['Execução e hábitos', 'checksq', ['tasks', 'hab', 'focus']], ['Fé', 'cross', ['faith']]];
const EVAI = { busy: false, err: '' };
const evoData = () => { const M = I.metrics.filter(m => !m.has || m.has()), by = {}; M.forEach(m => { const v = I.compare(m); const cmp = (a, b2) => a == null || b2 == null || Math.abs(a - b2) <= Math.abs(b2) * .02 ? null : (m.up === false ? a < b2 : a > b2); by[m.k] = { m, v, up: cmp(v[0], v[1]), upY: cmp(v[0], v[3]) }; }); return by; };
